function sbFetch(path, opts) {
  opts = opts || {};
  opts.headers = Object.assign({
    'apikey': SB_KEY,
    'Authorization': 'Bearer ' + SB_KEY,
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  }, opts.headers || {});
  return fetch(SB_URL + '/rest/v1/' + path, opts);
}


function sbRpc(fnName, params) {
  return fetch(SB_URL + '/rest/v1/rpc/' + fnName, {
    method: 'POST',
    headers: {
      'apikey': SB_KEY,
      'Authorization': 'Bearer ' + SB_KEY,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation'
    },
    body: JSON.stringify(params || {})
  }).then(function(r) {
    if (!r.ok) {
      return r.text().then(function(txt) {
        var e = null;
        try { e = JSON.parse(txt); } catch(x) {}
        var msg = (e && e.message) || txt || 'Ошибка запроса';
        // Сервер сам сообщает, что токен администратора истёк/недействителен
        // (см. kv_check_admin_token в schema.sql) — в этом случае сразу
        // разлогиниваем и отправляем на экран входа администратора,
        // вместо того чтобы показывать сотруднику голую "Ошибку".
        if (/сесси.*(недействительна|истекла)|требуется авторизация администратора/i.test(msg)) {
          kvLogout('login-admin.html');
        }
        throw new Error(msg);
      });
    }
    
    return r.text().then(function(txt) {
      if (!txt || txt.trim() === '' || txt.trim() === 'null') return null;
      try { return JSON.parse(txt); } catch(x) { return null; }
    });
  });
}


// Сессия (и сотрудника, и администратора) живёт максимум 12 часов, после чего
// нужно зайти заново — почтой (сотрудник) или логином/паролем (администратор).
// Проверяется по времени входа, сохранённому в браузере — без каких-либо
// IP-адресов или иной информации об устройстве.
var KV_SESSION_TTL_MS = 12 * 60 * 60 * 1000;

function kvGetMe() {
  var stored = localStorage.getItem('kv_me');
  if (!stored) return null;
  var me;
  try { me = JSON.parse(stored); } catch(e) { return null; }
  if (!me || !me.kv_login_at || (Date.now() - me.kv_login_at) > KV_SESSION_TTL_MS) {
    localStorage.removeItem('kv_me');
    return null;
  }
  return me;
}
function kvSetMe(user) {
  var withTimestamp = Object.assign({}, user, { kv_login_at: Date.now() });
  localStorage.setItem('kv_me', JSON.stringify(withTimestamp));
}
function kvLogout(redirectTo) {
  var me = kvGetMe();
  localStorage.removeItem('kv_me');
  if (me && me.token) {
    // Аннулируем токен на сервере (см. kv_admin_logout в schema.sql), чтобы
    // он не мог быть использован повторно. Не ждём ответа — выходим сразу.
    sbRpc('kv_admin_logout', { p_token: me.token }).catch(function(){});
  }
  window.location.href = redirectTo || 'index.html';
}


function kvRequireAuth(requiredRole) {
  var me = kvGetMe();
  if (!me) {
    window.location.href = requiredRole === 'admin' ? 'login-admin.html' : 'index.html';
    return null;
  }
  if (requiredRole === 'admin' && me.role !== 'admin') {
    window.location.href = 'forms.html';
    return null;
  }
  kvStartSessionWatch(requiredRole);
  return me;
}

// Если вкладка остаётся открытой дольше 12 часов, сессия истечёт "молча" —
// без этой проверки человек узнал бы об этом только при следующем клике,
// получив непонятную "Ошибку". Раз в 5 минут проверяем срок действия и,
// если он истёк, сразу отправляем на нужный экран входа.
var KV_SESSION_WATCH_STARTED = false;
function kvStartSessionWatch(requiredRole) {
  if (KV_SESSION_WATCH_STARTED) return;
  KV_SESSION_WATCH_STARTED = true;
  setInterval(function() {
    if (!kvGetMe()) {
      window.location.href = requiredRole === 'admin' ? 'login-admin.html' : 'index.html';
    }
  }, 5 * 60 * 1000);
}


function kvInitTheme() {
  if (localStorage.getItem('kv_dk') === '1') document.documentElement.classList.add('dk');
}
function togTheme() {
  var d = document.documentElement.classList.toggle('dk');
  localStorage.setItem('kv_dk', d ? '1' : '0');
}


function kvInitFavicon() {
  var link = document.querySelector("link[rel~='icon']");
  if (!link) {
    link = document.createElement('link');
    link.rel = 'icon';
    document.head.appendChild(link);
  }
  link.href = KV_LOGO;
}

// ===== Новости: сжатие картинок перед сохранением в базу =====
// Картинки хранятся как base64 прямо в строке kv_news (без отдельного
// storage-бакета), поэтому перед сохранением уменьшаем их до разумного
// размера и пережимаем в JPEG, чтобы не раздувать таблицу.
function kvCompressImage(file, maxDim, quality) {
  maxDim = maxDim || 1280;
  quality = quality || 0.72;
  return new Promise(function(resolve, reject) {
    if (!file || !/^image\//.test(file.type)) { reject(new Error('Файл не является изображением')); return; }
    var reader = new FileReader();
    reader.onerror = function() { reject(new Error('Не удалось прочитать файл')); };
    reader.onload = function(e) {
      var img = new Image();
      img.onerror = function() { reject(new Error('Не удалось загрузить изображение')); };
      img.onload = function() {
        var w = img.width, h = img.height;
        if (w > maxDim || h > maxDim) {
          if (w >= h) { h = Math.round(h * maxDim / w); w = maxDim; }
          else { w = Math.round(w * maxDim / h); h = maxDim; }
        }
        var canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        var ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, w, h);
        try {
          resolve(canvas.toDataURL('image/jpeg', quality));
        } catch (err) {
          reject(err);
        }
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  });
}

// ===== Новости: отметить как прочитанное (upsert) =====
// Один сотрудник — одна запись на новость (unique(news_id, user_email) в базе).
// Повторный вызов просто обновит read_at вместо ошибки дубликата.
function kvMarkNewsRead(newsId, userEmail, userName) {
  return sbFetch('kv_news_reads?on_conflict=news_id,user_email', {
    method: 'POST',
    headers: { 'Prefer': 'resolution=merge-duplicates,return=representation' },
    body: JSON.stringify({ news_id: newsId, user_email: userEmail, user_name: userName || null, read_at: new Date().toISOString() })
  }).then(function(r) {
    if (!r.ok) throw new Error('Не удалось сохранить отметку');
    return r.json();
  });
}

function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function fmtDate(s) {
  if (!s) return '—';
  var d = new Date(s);
  return d.getDate()+'.'+(d.getMonth()+1)+'.'+d.getFullYear();
}
function setEl(id, v) { var el=document.getElementById(id); if(el) el.textContent=v; }
function openModal(id) { var el=document.getElementById(id); if(el) el.classList.add('on'); }
function closeModal(id) { var el=document.getElementById(id); if(el) el.classList.remove('on'); }
function toast(msg, type) {
  var wrap = document.getElementById('toast');
  if (!wrap) return;
  var el = document.createElement('div');
  el.className = 'toast-item' + (type ? ' '+type : '');
  el.textContent = msg;
  wrap.appendChild(el);
  setTimeout(function(){ el.remove(); }, 3000);
}
function kvBindOverlayClose() {
  document.querySelectorAll('.overlay').forEach(function(ov) {
    ov.addEventListener('click', function(e) {
      if (e.target === ov) ov.classList.remove('on');
    });
  });
}

function kvInitMobileMenu() {
  var toggle = document.getElementById('menu-toggle');
  var sb = document.querySelector('.sb');
  if (!toggle || !sb) return;

  var overlay = document.createElement('div');
  overlay.className = 'sb-overlay';
  document.body.appendChild(overlay);

  function closeMenu() {
    sb.classList.remove('open');
    toggle.classList.remove('on');
    overlay.classList.remove('on');
  }
  function openMenu() {
    sb.classList.add('open');
    toggle.classList.add('on');
    overlay.classList.add('on');
  }

  toggle.addEventListener('click', function() {
    if (sb.classList.contains('open')) closeMenu(); else openMenu();
  });
  overlay.addEventListener('click', closeMenu);

  sb.querySelectorAll('.lb').forEach(function(btn){
    btn.addEventListener('click', function(){
      if (window.innerWidth <= 768) closeMenu();
    });
  });
}

// ===== PWA: регистрация service worker =====
// Даёт возможность "установить" сайт на телефон (иконка на главном экране,
// запуск без адресной строки браузера) и ускоряет повторные загрузки статики.
// Сами данные (Supabase) не кэшируются — см. комментарии в sw.js.
if ('serviceWorker' in navigator) {
  window.addEventListener('load', function() {
    navigator.serviceWorker.register('sw.js').catch(function(err) {
      console.warn('Service worker не зарегистрирован:', err);
    });
  });
}
